const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs');const assert=require('assert');
(async()=>{const b=await chromium.launch();const c=await b.newContext();const p=await c.newPage();const root='http://127.0.0.1:4181';const logs=[];const log=(n,d)=>{logs.push({n,d});console.log(n,JSON.stringify(d))};let authHeader=null;p.on('request',r=>{if(r.url().includes('/api/admin/v1/'))authHeader=r.headers().authorization||authHeader});
await p.goto(root+'/ro/account');await p.locator('[name=email]').fill('client@dracula-design.com');await p.locator('[name=password]').fill(process.env.QA_PASSWORD);await p.locator('form button[type=submit]').click();await p.waitForSelector('[data-action=logout]');await p.locator('[data-action=order]').first().click();await p.locator('#image-dialog').waitFor({state:'visible'});const labels=await p.locator('#image-dialog').evaluate(d=>({name:d.getAttribute('aria-label'),close:d.querySelector('button').getAttribute('aria-label')}));assert(labels.name&&labels.close);log('order-dialog',labels);await p.keyboard.press('Escape');
await p.goto(root+'/ro/collection');await p.waitForSelector('.product');await p.locator('[data-filter=accesorii]').click();assert.equal(await p.locator('[data-filter=accesorii]').getAttribute('aria-pressed'),'true');log('filter-aria','pass');await p.locator('.product-image').first().click();await p.locator('[data-action=image]').click();const imageLabels=await p.locator('#image-dialog').evaluate(d=>({name:d.getAttribute('aria-label'),close:d.querySelector('button').getAttribute('aria-label')}));assert(imageLabels.name&&imageLabels.close);log('image-dialog',imageLabels);await p.keyboard.press('Escape');await p.locator('[data-action=add]').first().click();await p.waitForTimeout(250);
const csrf=(await c.cookies()).find(x=>x.name==='dracula_csrf').value;const headers={'X-CSRF-Token':csrf};const cart=await p.request.get(root+'/api/cart').then(r=>r.json());const pid=cart.items[0].product_id;const body={customer:{first_name:'QA',last_name:'Reaudit',email:'client@dracula-design.com',phone:'0722123456'},shipping_address:{line1:'TEST AUDIT',city:'Brasov',county:'Brasov',postal_code:'500001',country:'RO'},delivery_method:'courier',payment_method:'cash_on_delivery',accept_terms:true,expected_total_ron:0,notes:'NEGATIVE REAUDIT'};
for(const [n,value]of [['object',{}],['array',[]],['bool',true],['negative',-1],['string','10'],['null',null]]){const r=await p.request.post(root+'/api/orders',{headers:{...headers,'Idempotency-Key':'reaudit-'+Date.now()+'-'+n},data:{...body,expected_total_ron:value}});assert.equal(r.status(),400,n);log('invalid-total-'+n,r.status())}
for(const value of ['NaN','Infinity','-Infinity']){const data=JSON.stringify(body).replace('"expected_total_ron":0','"expected_total_ron":'+value);const r=await p.request.post(root+'/api/orders',{headers:{...headers,'Content-Type':'application/json','Idempotency-Key':'reaudit-'+Date.now()+'-'+value},data});assert.equal(r.status(),400,value);log('invalid-total-'+value,r.status())}
for(const qty of [1.5,true,{},[],null,-1]){const r=await p.request.patch(root+'/api/cart/items/'+pid,{headers,data:{qty}});assert.equal(r.status(),400,JSON.stringify(qty));log('invalid-quantity-'+JSON.stringify(qty),r.status())}
const zero=await p.request.patch(root+'/api/cart/items/'+pid,{headers,data:{qty:0}});assert.equal(zero.status(),200);assert.equal((await p.request.get(root+'/api/cart').then(r=>r.json())).items.length,0);log('quantity-zero-delete',200);
await p.goto(root+'/admin/login?ui=classic');await p.locator('input[type=email]').fill('admin@dracula-design.com');await p.locator('input[type=password]').fill(process.env.QA_PASSWORD);await p.locator('[data-testid=login-submit]').click();await p.waitForTimeout(500);await p.goto(root+'/admin/categories?ui=classic');await p.waitForTimeout(500);const h={'X-Requested-With':'XMLHttpRequest',...(authHeader?{Authorization:authHeader}:{})};const admin=await p.request.get(root+'/api/admin/v1/categories',{headers:h});assert.equal(admin.status(),200);const json=await admin.json();const rows=json.items||json.data||json;const counts=rows.map(x=>({id:x.external_id,count:x.product_count}));for(const [id,count]of Object.entries({business:2,everyday:1,women:2,haine:0,accesorii:5}))assert.equal(counts.find(x=>x.id===id).count,count);log('category-counts',counts);await p.screenshot({path:'outputs/dracula-design-office/audit-admin-after.png',fullPage:true});
const code='qa-audit-'+Date.now();const create=await p.request.post(root+'/api/admin/v1/categories',{headers:h,data:{external_id:code,name:{ro:'QA Audit temp'},description:{ro:'QA description keep'},is_active:true}});assert.equal(create.status(),201);const category=await create.json();try{const active=await p.request.get(root+'/api/dracula/bootstrap').then(r=>r.json());assert(active.categories.some(x=>x.code===code));const patch=await p.request.patch(root+'/api/admin/v1/categories/'+category.id,{headers:h,data:{is_active:false,name:{ro:'QA Audit updated'}}});assert.equal(patch.status(),200);const updated=await patch.json();assert.equal(updated.description.ro,'QA description keep');const inactive=await p.request.get(root+'/api/dracula/bootstrap').then(r=>r.json());assert(!inactive.categories.some(x=>x.code===code));log('inactive-category-hidden-and-description-kept','pass');}finally{const deleted=await p.request.delete(root+'/api/admin/v1/categories/'+category.id+'?hard=1',{headers:h});log('temporary-category-cleanup',deleted.status());assert.equal(deleted.status(),200)}
await b.close();fs.writeFileSync('work/reaudit-design-results.json',JSON.stringify(logs,null,2));})().catch(e=>{console.error(e);process.exit(1)});
